PARAMS = {}

def sig(x):
    return 0.5 * (1.0 + np.tanh(0.5 * x))

def build(L, D, SEP, V):
    d = 8 * L + 32
    K = 30.0
    A = 60.0
    c = 0.38
    P = {}
    for g in ['r', 'i', 'o', 'u']:
        P['Wy' + g] = np.zeros((d, d), dtype=np.float32)
        P['We' + g] = np.zeros((d, d), dtype=np.float32)
        P['b' + g] = np.zeros(d, dtype=np.float32)
    E = np.zeros((V, d), dtype=np.float32)
    for x in range(D):
        E[x, 0] = 1.0 if (x & 1) else -1.0
        E[x, 1] = 1.0 if (x & 2) else -1.0
    O = np.zeros((d, V), dtype=np.float32)
    z = 0
    def q(k):
        return 1 + k
    def slot(p, b):
        return 1 + 2 * L + 2 * p + b
    # start unit z: becomes +1 after first token
    P['br'][z] = -K; P['bi'][z] = K; P['bo'][z] = K; P['bu'][z] = K
    # position counter q_k positive after token k
    for k in range(2 * L):
        j = q(k)
        P['br'][j] = -K; P['bi'][j] = K; P['bo'][j] = K
        if k == 0:
            P['Wyu'][j, z] = -A; P['bu'][j] = A * c
        else:
            P['Wyu'][j, q(k - 1)] = A; P['bu'][j] = -A * c
    # slots: two sign bits per source position
    for p in range(L):
        for b in range(2):
            j = slot(p, b)
            P['br'][j] = K
            if p == 0:
                P['Wyi'][j, z] = -A; P['bi'][j] = A * c
            else:
                P['Wyi'][j, q(p - 1)] = A; P['bi'][j] = -A * c
            P['Weu'][j, b] = K
            P['Wyo'][j, q(L + p - 1)] = A; P['bo'][j] = -A * c
            for s in range(D):
                bit = (s >> b) & 1
                O[j, s] = 1.0 if bit else -1.0
    P['E'] = E
    P['O'] = O
    P['d'] = d
    return P

def init(layout):
    L = int(layout['size'])
    D = int(layout['D'])
    SEP = int(layout['SEP'])
    V = int(layout['vocab'])
    key = (L, D, SEP, V)
    if PARAMS.get('key') != key:
        PARAMS.clear()
        PARAMS.update(build(L, D, SEP, V))
        PARAMS['key'] = key
    d = PARAMS['d']
    return {'s': np.zeros(d, dtype=np.float32), 'y': np.zeros(d, dtype=np.float32)}

def update(state, token):
    P = PARAMS
    y = state['y'].astype(np.float64)
    s = state['s'].astype(np.float64)
    e = P['E'][int(token)].astype(np.float64)
    def pre(g):
        return P['Wy' + g].astype(np.float64) @ y + P['We' + g].astype(np.float64) @ e + P['b' + g].astype(np.float64)
    r = sig(pre('r'))
    i = sig(pre('i'))
    o = sig(pre('o'))
    u = np.tanh(pre('u'))
    s = r * s + i * u
    s32 = s.astype(np.float32)
    y32 = (o * np.tanh(s32.astype(np.float64))).astype(np.float32)
    return {'s': s32, 'y': y32}

def predict(state):
    logits = state['y'].astype(np.float64) @ PARAMS['O'].astype(np.float64)
    return int(np.argmax(logits))

