PARAMS = {}

def sg(x):
    return (0.5 * (1.0 + np.tanh(0.5 * x))).astype(np.float32)

def build(layout):
    K = layout['size']
    V = layout['V']
    nk = layout['n_keys']
    kb = layout['key_base']
    vb = layout['value_base']
    vocab = layout['vocab']
    d = 8 * K + 32
    tp = np.linspace(-0.9, 0.9, V).astype(np.float32)
    E = np.zeros((vocab, d))
    for v in range(V):
        E[vb + v, 0] = 1.0
        E[vb + v, 1] = np.arctanh(float(tp[v]))
    for k in range(nk):
        E[kb + k, 2 + k] = 1.0
    names = ['r', 'i', 'o', 'u']
    Wy = {n: np.zeros((d, d)) for n in names}
    We = {n: np.zeros((d, d)) for n in names}
    b = {n: np.zeros(d) for n in names}
    c1 = float(np.tanh(np.float32(1.0)))
    # constant cell 0
    b['r'][0] = -30.0; b['i'][0] = 30.0; b['u'][0] = 20.0; b['o'][0] = 30.0
    for k in range(nk):
        a = 1 + k
        bc = 1 + nk + k
        # key indicator cell: holds 1 iff current token is key k
        b['r'][a] = -30.0; b['i'][a] = 30.0; We['u'][a, 2 + k] = 20.0; b['o'][a] = 30.0
        # value store cell for key k: written when a value token follows key k
        b['r'][bc] = 30.0
        Wy['i'][bc, a] = 40.0 / c1
        We['i'][bc, 0] = 40.0
        b['i'][bc] = -60.0
        We['u'][bc, 1] = 1.0
        We['o'][bc, 2 + k] = 40.0
        b['o'][bc] = -20.0
    w = np.tanh(tp).astype(np.float64)
    O = np.zeros((d, vocab))
    for k in range(nk):
        bc = 1 + nk + k
        for v in range(V):
            O[bc, vb + v] = 2.0 * w[v]
    for v in range(V):
        O[0, vb + v] = (10.0 - w[v] * w[v]) / c1
    P = {'E': E.astype(np.float32), 'O': O.astype(np.float32)}
    for n in names:
        P['Wy' + n] = Wy[n].astype(np.float32)
        P['We' + n] = We[n].astype(np.float32)
        P['b' + n] = b[n].astype(np.float32)
    return d, P

def init(layout):
    d, P = build(layout)
    PARAMS[d] = P
    return (np.zeros(d, dtype=np.float32), np.zeros(d, dtype=np.float32))

def update(state, token):
    s, y = state
    P = PARAMS[s.shape[0]]
    e = P['E'][int(token)]
    def lin(n):
        return (P['Wy' + n] @ y + P['We' + n] @ e + P['b' + n]).astype(np.float32)
    r = sg(lin('r'))
    i = sg(lin('i'))
    o = sg(lin('o'))
    u = np.tanh(lin('u')).astype(np.float32)
    s2 = (r * s + i * u).astype(np.float32)
    y2 = (o * np.tanh(s2)).astype(np.float32)
    return (s2, y2)

def predict(state):
    s, y = state
    P = PARAMS[s.shape[0]]
    scores = y @ P['O']
    return int(np.argmax(scores))
